  },
  summaryValue: {
    fontSize: typography.body2.fontSize,
    color: colors.text,
    fontWeight: '500',
  },
  summaryDivider: {
    marginVertical: spacing.sm,
  },
  totalLabel: {
    fontSize: typography.body1.fontSize,
    fontWeight: '600',
    color: colors.text,
  },
  totalValue: {
    fontSize: typography.body1.fontSize,
    fontWeight: '600',
    color: colors.primary,
  },
  actionButtons: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: spacing.lg,
  },
  cancelButton: {
    flex: 0.48,
    borderColor: colors.error,
    borderWidth: 1,
    borderRadius: 28,
  },
  confirmButton: {
    flex: 0.48,
  },
  buttonContent: {
    paddingVertical: spacing.sm,
  },
  cancelButtonContent: {
    paddingVertical: spacing.sm,
    justifyContent: 'center',
  },
  securityHeader: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: spacing.sm,
  },
  securityTitle: {
    fontSize: typography.body1.fontSize,
    fontWeight: '600',
    color: colors.text,
    marginLeft: spacing.sm,
  },
  securityText: {
    fontSize: typography.caption.fontSize,
    color: colors.textSecondary,
    lineHeight: typography.caption.lineHeight,
  },
  // Custom Dialog Styles
  overlay: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    backgroundColor: 'rgba(0, 0, 0, 0.5)',
    justifyContent: 'center',
    alignItems: 'center',
    zIndex: 1000,
  },
  confirmationDialog: {
    backgroundColor: colors.white,
    borderRadius: 12,
    padding: spacing.lg,
    margin: spacing.lg,
    minWidth: 280,
    elevation: 8,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.3,
    shadowRadius: 8,
  },
  dialogTitle: {
    fontSize: 18,
    fontWeight: '600',
    color: colors.text,
    marginBottom: spacing.sm,
    textAlign: 'center',
  },
